namespace Bevy;

/// <summary>
/// A generated byte mirror of one of Bevy's components, which carries the layout it was generated
/// from.
/// </summary>
/// <remarks>
/// The generator writes each mirror's fields at the offsets the description holds for its
/// component, which the schema dump read from the bridge. A Bevy release that moves a field leaves
/// the mirror reading the wrong bytes, so the bridge's own reading is compared with this one the
/// first time the mirror's id is asked for in a world, and a difference refuses the mirror rather
/// than corrupting the component.
/// </remarks>
internal interface IMirroredLayout
{
    /// <summary>The layout the mirror was generated from, as <see cref="ReflectedLayouts.Signature"/> writes one.</summary>
    string Layout { get; }
}
